// coloca a los personajes de una escena (los demás, ocultos) y los objetos que se ven en ella
function bodaLay(S,spec,objs,lt){
  for(const k in S.a){const o=S.a[k];o.visible=false;o.userData.fixY=false;o.rotation.set(0,0,0);o.rotation.order='XYZ';const ar=o.userData.arms;if(ar){ar[0].rotation.set(0,0,0);ar[1].rotation.set(0,0,0);}o.userData.pose=0;}
  for(const k in spec){const[x,z,r]=spec[k],o=S.a[k];o.visible=true;o.position.set(x,0,z);o.rotation.y=r||0;}
  const O=S.obj;for(const k of['lampN','lampG','altar','altarF','sheep','tabs','hasta','cake','vittae','lectus','brasero','fuego','agua'])O[k].visible=!!(objs&&objs.includes(k));
  if(O.lampN.userData.s===undefined)for(const k of['lampN','lampG','altarF','fuego'])O[k].userData.s=O[k].scale.x;
  for(const n of O.nuts){n.m.visible=false;n.t=-1;}
  if(lt){O.light.position.set(O.ox+lt[0],O.oy+lt[1],O.oz+lt[2]);O.light.intensity=lt[3];}else O.light.intensity=0;
}
