function bodaAt(s){let i=0;for(;i<BODA_RUTA.length-1;i++){const a=BODA_RUTA[i],b=BODA_RUTA[i+1],l=Math.hypot(b[0]-a[0],b[1]-a[1]);if(s<=l||i===BODA_RUTA.length-2){const u=clamp(s/l,0,1);return[lerp(a[0],b[0],u),lerp(a[1],b[1],u),Math.atan2(b[0]-a[0],b[1]-a[1])];}s-=l;}}
