// serpientes, carros y Pegaso para las esferas de los destinos
function epiSnake(S,n,col,sz){const a=[],m=lam(col);for(let i=0;i<n;i++){const s=new THREE.Mesh(new THREE.SphereGeometry((sz||0.9)*(1-i/n*0.7),10,8),m.clone());s.castShadow=true;S.g.add(s);a.push(s);}return a;}
function snakeCoil(a,cx,cz,t,rise,sc){sc=sc||1;const n=a.length;a.forEach((s,i)=>{const k=i/n,an=k*TAU*2+t*0.3,rd=(0.6+k*3)*sc;s.position.set(cx+Math.cos(an)*rd,s.geometry.parameters.radius+(i<6?(6-i)/6*3*rise*sc:0),cz+Math.sin(an)*rd);});}
function chariotK(S,col,who){const c=new THREE.Group(),m=lam(col),dk=lam('#3a2a1e');box(1.6,0.9,1.2,m,0,1.1,0,c);box(0.12,0.12,3.2,dk,0,0.9,2.2,c);
  const wh=[];for(const s of[-1,1]){const w=new THREE.Mesh(new THREE.CylinderGeometry(0.7,0.7,0.12,16),dk);w.rotation.z=Math.PI/2;w.position.set(s*1.1,0.7,0);c.add(w);wh.push(w);}
  const hs=[makeBeast('caballo',c,-0.7,4.2,0),makeBeast('caballo',c,0.7,4.2,0)];const p=makePerson(Object.assign({noVary:true},who));p.position.set(0,0.6,-0.1);c.add(p);
  c.userData={wheels:wh,horses:hs,who:p};S.g.add(c);return c;}
function raceX(t,i){const k=clamp(t/14,0,1);return i?lerp(-125,84,k*k*0.3+k*0.7):lerp(-100,94,k);}
function chariotRun(c,t){c.userData.horses.forEach((h,i)=>walkLegs(h,t*10+i,0.6));}
function pegasusK(S){const g=new THREE.Group();makeBeast('caballo',g,0,0,0);const ws=[];for(const s of[-1,1]){const pv=new THREE.Group();pv.position.set(s*0.35,1.55,0.3);box(1.8,0.06,0.9,lam('#f4f2ec'),s*0.9,0,0,pv);g.add(pv);ws.push(pv);}g.userData.wings=ws;S.g.add(g);return g;}
function pegFlap(g,t,fly){g.userData.wings.forEach((w,i)=>{w.rotation.z=(i?-1:1)*(fly?Math.sin(t*8)*0.6:-0.25);});}
