   A.gr=[];for(let i=0;i<30;i++){const r=Math.floor(i/10),f=i%10;A.gr.push(S.person({chiton:'#9a2a1e',himation:'#7a1e18',short:true,noHimation:true,beard:true,hair:'#3a2a18',helmet:'attic',attrs:['P_spear','P_spearhead','P_shield']},2+r*1.6,-12+f*2.6,-Math.PI/2));}
