   A.al=[];for(let i=0;i<10;i++)A.al.push(S.person({chiton:pick(['#5a6a7a','#7a6a3a','#4a5a3a']),short:true,noHimation:true,beard:true,hair:'#3b2a1e',helmet:'attic',attrs:['P_spear','P_spearhead','P_shield']},6+(i%2)*2,-12+i*2.6,-Math.PI/2));
   A.per=[];for(let i=0;i<40;i++){const c=pick(['#6a4a8a','#3a5a7a','#8a6a2a','#7a2a3a','#4a6a4a']);A.per.push(S.person({chiton:c,himation:c,short:true,noHimation:true,beard:true,hair:'#1a1410',spear:true},0,0,Math.PI/2));}
   A.imm=[];for(let i=0;i<12;i++){const p=S.person({chiton:'#efe6d4',himation:'#2f3f6a',short:true,noHimation:true,beard:true,hair:'#1a1410',spear:true},0,0,0);const f=fireSprite(S,0,0,0,1.2);A.imm.push([p,f]);}
   A.scout=S.beast('caballo',-35,12,Math.PI/2);A.rider=S.person({chiton:'#6a4a8a',short:true,noHimation:true,beard:true,hair:'#1a1410'},-35,12,Math.PI/2);
   A.arw=[];for(let i=0;i<30;i++){const a=S.box(0.05,0.05,1.1,'#2a2420',0,0,0);a.visible=false;A.arw.push(a);}
   A.lion=new THREE.Group();const st=lam('#cdbf9f');box(1.6,1.2,3.2,st,0,1.6,0,A.lion);box(1.8,1.8,1.4,st,0,2.4,1.8,A.lion);for(const[px,pz]of[[-0.6,-1.2],[0.6,-1.2],[-0.6,1.2],[0.6,1.2]])box(0.4,1,0.4,st,px,0.5,pz,A.lion);box(3,0.5,4.4,st,0,0.25,0,A.lion);A.lion.position.set(22,3,-6);A.lion.rotation.y=-Math.PI/2;S.g.add(A.lion);
