   A.hip=S.person({female:true,chiton:'#efe6d4',himation:'#c96a8a',hair:'#5a3a22',veil:true},4,-24,0);A.myr=S.person({chiton:'#bfae8a',short:true,hair:'#3a2a1e'},-8,-22,0);
