   A.ath=S.person({female:true,chiton:'#efe6d4',himation:'#c9a24a',hair:'#5a3a22',helmet:'attic',glow:'#ffe2a0',attrs:['G_aegis','P_spear','P_spearhead','P_shield'],scale:1.3},22,0,10);A.bridle=glowSprite(S,0,0,0,1.6,0xffd27a);
